<?php use LipePool\Support\View; ?>
<section class="page-heading container"><p class="eyebrow">Área administrativa</p><h1>Clientes</h1><p class="lead">Dados de contato necessários para organizar os atendimentos.</p></section>
<section class="container section"><form method="get" action="/admin/clientes" class="search-form"><label class="sr-only" for="q">Buscar cliente</label><input id="q" name="q" value="<?= View::escape($search) ?>" maxlength="100" placeholder="Buscar por nome ou e-mail"><button class="button button-primary" type="submit">Buscar</button></form>
<?php if (!$customers): ?><div class="empty-state"><p>Nenhum cliente encontrado.</p></div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Nome</th><th>E-mail</th><th>Telefone</th><th>Cadastro</th></tr></thead><tbody><?php foreach ($customers as $customer): ?><tr><td><?= View::escape($customer['name']) ?></td><td><a href="mailto:<?= View::escape($customer['email']) ?>"><?= View::escape($customer['email']) ?></a></td><td><?= View::escape($customer['phone']) ?></td><td><?= View::escape(date('d/m/Y', strtotime($customer['created_at']))) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
